<?php
$filas=is_array($raw['componentes']??null)?array_values($raw['componentes']):[];
if(!$filas)$filas=[[]];
$esPresentacion=$esPresentacion??false;
$pintarComponente=static function($i,$c)use($esc,$opcionesArticulos,$opcionesVersiones,$esPresentacion):void{if(!is_array($c))$c=[]; ?>
<fieldset class="m2-componente" data-m2-row><legend>Componente <span data-m2-numero><?= is_int($i)?$i+1:'' ?></span></legend>
<div class="admin-form-grid">
<?php if($esPresentacion): ?><input type="hidden" name="componentes[<?= $esc($i) ?>][etapa]" value="<?= $esc($c['etapa']??'servicio') ?>"><?php endif; ?>
<label class="admin-field">Artículo o preparación<select name="componentes[<?= $esc($i) ?>][articulo_id]" required data-m2-articulo><option value="">Selecciona un artículo o preparación</option><?php foreach($opcionesArticulos as $a): ?><option value="<?= (int)$a['id'] ?>" data-unidad="<?= $esc($a['unidad']) ?>" <?= (string)($c['articulo_id']??'')===(string)$a['id']?'selected':'' ?> <?= empty($a['activo'])&&(string)($c['articulo_id']??'')!==(string)$a['id']?'disabled':'' ?>><?= $esc($a['nombre'].' · '.$a['unidad'].(empty($a['activo'])?' · Inactivo':'')) ?></option><?php endforeach; ?></select></label>
<label class="admin-field">Cantidad<input name="componentes[<?= $esc($i) ?>][cantidad]" type="number" min="0.001" max="999999999.999" step="0.001" inputmode="decimal" required value="<?= $esc($c['cantidad']??'') ?>"></label>
<label class="admin-field">Unidad<select name="componentes[<?= $esc($i) ?>][unidad]" data-m2-unidad><?php foreach(['g','kg','ml','l','pza'] as $u): ?><option <?= ($c['unidad']??'g')===$u?'selected':'' ?>><?= $u ?></option><?php endforeach; ?></select></label>
<label class="admin-field">Cómo se consume<select name="componentes[<?= $esc($i) ?>][modalidad]" data-m2-modalidad><option value="almacenado" <?= ($c['modalidad']??'')==='almacenado'?'selected':'' ?>>Desde existencias del artículo</option><option value="desglosar" <?= ($c['modalidad']??'')==='desglosar'?'selected':'' ?>>Preparar usando su elaboración</option></select></label>
<label class="admin-field">Versión de elaboración<select name="componentes[<?= $esc($i) ?>][version_receta_id]" data-m2-version data-native><option value="">No ejecuta elaboración</option><?php foreach($opcionesVersiones as $v): ?><option value="<?= (int)$v['id'] ?>" data-articulo="<?= (int)$v['articulo_id'] ?>" <?= (string)($c['version_receta_id']??'')===(string)$v['id']?'selected':'' ?>><?= $esc($v['nombre'].' · v'.$v['version'].' · '.($v['slug']==='global'?'Casa':($v['slug']==='panaderia'?'Panadería':'Restaurante')).' · '.$v['rendimiento'].' '.$v['unidad']) ?></option><?php endforeach; ?></select><span class="admin-field__hint">La versión queda fijada. Cambiar la elaboración del artículo no modifica esta composición.</span></label>
<?php if(!$esPresentacion): ?><label class="admin-field">Merma prevista (%)<input name="componentes[<?= $esc($i) ?>][merma]" type="number" min="0" max="99.999" step="0.001" inputmode="decimal" value="<?= $esc($c['merma']??'0.000') ?>"></label><?php endif; ?>
</div><button type="button" class="admin-btn admin-btn--secondary admin-btn--small" data-m2-quitar>Quitar componente</button></fieldset>
<?php }; ?>
<div data-m2-builder><div data-m2-rows><?php foreach($filas as $i=>$c)$pintarComponente($i,$c); ?></div><template data-m2-template><?php $pintarComponente('__INDEX__',[]); ?></template><button type="button" class="admin-btn admin-btn--secondary" data-m2-agregar>Agregar componente</button><p class="admin-field__hint" data-m2-status role="status" aria-live="polite"><?= $esPresentacion ? 'Cantidades por presentación vendida.' : 'Las cantidades corresponden al rendimiento completo indicado.' ?></p><noscript><p>Para agregar más componentes activa JavaScript. Puedes revisar y guardar las filas existentes.</p></noscript></div>
